 #[test]fn native_6144_color_point_physics_retirement_and_gpu_primitive_records_match(){points(128,"native-water-points.jsonl",2425523601);}
 #[test]fn native_6144_flags_two_shape_physics_and_identical_gpu_geometry_match(){points(2,"ROUND39-shape-points.jsonl",4062574557);}
 fn points(flags:u8,file:&str,expected:u32){
  use super::super::{Particle,View,Primitive};let oracle=std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../work/parity-audit").join(file)).ok().map(|s|s.lines().map(|l|serde_json::from_str::<serde_json::Value>(l).unwrap()).collect::<Vec<_>>());let mut all=2166136261u32;let mut visible=0;
  for s in 0..192usize{let mode=s/64;let seed=s%64;let ox=[346,-180,4080,346][seed/16];let oy=[420,-100,4080,420][seed/16];let camera=usize::from(seed%2==0);let clip=seed/4%4;let mut b=std::array::from_fn(|j|(s*17+j*19)as u8);let mut rng=OriginalRng{words:std::array::from_fn(|i|0x173510a7u32.wrapping_add(s as u32*7919).wrapping_add((i as u32).wrapping_mul(0x9e3779b9))),multiplayer:false};initialize(&mut b,Context{origin:[ox,oy],tint:9,flags,fade:128,owner:0,sprite:0},||rng.next_u32());let initial=b;let mut p=Particle::from_bytes(b);assert_eq!(p.bytes(),b);let view=View{camera:[(camera*40)as i16,(camera*60)as i16],clip:[[-32768,-32768,32767,32767],[400,400,600,600],[0,0,320,200],[-1,-1,4096,4096]][clip],world:[4096,4096],sine:-898,cosine:493};let mut last=[0,0];
   for tick in 0..32usize{let step=p.advance_native(view,&mut last);let mut vertices=Vec::new();let command=if let Some(d)=step.draw{assert_eq!(d.primitive,Some(Primitive::ColorPoint{color:9}));assert!(!d.transformed);let[x,y]=d.screen;let scale=if mode==2{2.0}else{1.0};for n in[y,x,y,x.wrapping_add(1),y.wrapping_add(1),x.wrapping_add(1),y.wrapping_add(1),x]{vertices.extend_from_slice(&(f32::from(n)*scale).to_le_bytes());}visible+=1;if mode==2{-521}else{-9}}else{0};let current=p.bytes();assert_eq!(current[23],initial[23],"the point branch does not advance phase");assert_eq!(current[24],initial[24]);let values=[s as u32,tick as u32,mode as u32,seed as u32,ox as u32,oy as u32,camera as u32,clip as u32,hash(initial),hash(current),u32::from(step.draw.is_some()),command as u32,hash(vertices.iter().copied()),last[0]as u32,last[1]as u32];for n in values{mix(&mut all,n);}if let Some(rows)=&oracle{let row=&rows[s*32+tick];let hex=|b:&[u8]|b.iter().map(|v|format!("{v:02x}")).collect::<String>();assert_eq!(row["initial"],hex(&initial));assert_eq!(row["bytes"],hex(&current),"point{s}/{tick}");assert_eq!(row["vertices"],hex(&vertices));assert_eq!(row["command"].as_i64().unwrap(),i64::from(command));assert_eq!(row["batch"].as_u64().unwrap(),u64::from(step.draw.is_some()));assert_eq!([row["projectX"].as_i64().unwrap(),row["projectY"].as_i64().unwrap()],[i64::from(last[0]),i64::from(last[1])]);}}
   assert!(!p.active);
  }assert_eq!(visible,426);assert_eq!(all,expected,"real4028a0/4027f0/403450 and467c70/467d60 or467e90 batch writers; final GPU rasterization remains an endpoint");
 }
